    def subsetsWithDup(self, nums: List[int]) -> List[List[int]]:
        nums.sort()
        res, path = [], []

        def dfs(start):
            res.append(path[:])
            for i in range(start, len(nums)):
                if i > start and nums[i] == nums[i - 1]:
                    continue
                path.append(nums[i])
                dfs(i + 1)
                path.pop()

        dfs(0)
        return res

class Solution:
    def restoreIpAddresses(self, s: str) -> List[str]:
        n = len(s)
        res, path = [], []

        def ok(a, b):
            if b - a + 1 > 3:
                return False
            if b - a + 1 > 1 and s[a] == "0":
                return False
            return int(s[a:b + 1]) <= 255

        def dfs(start):
            if len(path) == 4:
                if start == n:
                    res.append(".".join(path))
                return
            for i in range(start, min(start + 3, n)):
                if not ok(start, i):
                    break
                path.append(s[start:i + 1])
                dfs(i + 1)
                path.pop()

        if 4 <= n <= 12:
            dfs(0)
        return res

