class Solution:
    def wiggleMaxLength(self, nums: List[int]) -> int:
        if len(nums) < 2:
            return len(nums)
        res, prev = 1, 0
        for i in range(1, len(nums)):
            diff = nums[i] - nums[i - 1]
            if diff == 0:
                continue
            cur = 1 if diff > 0 else -1
            if cur != prev:
                res += 1
                prev = cur
        return res

