class Solution:
    def monotoneIncreasingDigits(self, n: int) -> int:
        s = list(str(n))
        L = len(s)
        for i in range(L - 1, 0, -1):
            if s[i - 1] > s[i]:
                s[i - 1] = str(int(s[i - 1]) - 1)
                for j in range(i, L):
                    s[j] = "9"
        return int("".join(s))

